('advanced-native-438', '["phrase"]'::jsonb, '{"advanced-native-438-v1-audio":{"type":"mc","answers":["Understanding decisions and feeling the personal impact of separation."],"options":["Understanding decisions and feeling the personal impact of separation.","Only checking dates, with no emotional response described.","Only feeling moved, with no structure helping understanding.","Receiving a complete proof that every recording was factually accurate."]},"advanced-native-438-v2-reply":{"type":"mc","answers":["The structure aided understanding while the recordings carried feeling.","The timeline explained the decisions, and the voices made the separations personal.","It served both the head and the heart through clear context and personal voices.","We could follow the choices and feel what they meant to people."],"options":["The structure aided understanding while the recordings carried feeling.","The timeline explained the decisions, and the voices made the separations personal.","It served both the head and the heart through clear context and personal voices.","We could follow the choices and feel what they meant to people."]},"advanced-native-438-v1-scene":{"type":"mc","answers":["It serves both the head and the heart without settling every question for me."],"options":["It serves both the head and the heart without settling every question for me.","I understood the reasoning about responsibility but had no emotional response to the farewell.","The farewell moved me, but the characters’ reasons remained impossible to understand."]},"advanced-native-438-v1-contrast":{"type":"mc","answers":["A list of facts with no described feeling or human connection."],"options":["A list of facts with no described feeling or human connection.","A work that prompts questions and evokes sympathy.","Clear explanation together with a personal emotional connection."]},"advanced-native-438-v1-branch":{"type":"mc","answers":["Keep the emotional voices and the context that helps us unde